module top_module(
  input wire clk,         // Added clk input
  input wire in,
  output wire out_modulator,
  output wire out_demodulator
);parameter osr = 128; // oversampling ratio
parameter order = 2; // order of the sigma-delta modulator

// Sigma-delta modulator
reg [order-1:0] integrator;
reg [order-1:0] quantizer;
reg [order-1:0] feedback;

always @(posedge clk) begin
  integrator <= {integrator[order-2:0], in} + feedback;
  quantizer <= integrator[order-1] ? -1 : 1;
  feedback <= quantizer - integrator[order-1];
end

assign out_modulator = quantizer[order-1];

// Sigma-delta demodulator
reg [osr-1:0] oversampled;
reg [osr-1:0] filtered;
reg [osr-1:0] analog;

always @(posedge clk) begin
  oversampled <= {oversampled[osr-2:0], in};
  filtered <= oversampled * osr;
  analog <= filtered / osr;
end

assign out_demodulator = analog[osr-1];

endmodule

