code:
module gray_code_counter(
  input clk,
  input rst_n,
  output reg [2:0] gray_code
);

  reg [2:0] state;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      gray_code <= 3'b000;
      state <= 3'b000;
    end
    else begin
      case (state)
        3'b000: gray_code <= 3'b000;
        3'b001: gray_code <= 3'b001;
        3'b011: gray_code <= 3'b011;
        3'b010: gray_code <= 3'b010;
        3'b110: gray_code <= 3'b110;
        3'b111: gray_code <= 3'b111;
        3'b101: gray_code <= 3'b101;
        3'b100: gray_code <= 3'b100;
        default: gray_code <= 3'b000;
      endcase

      state <= state + 1;
    end
  end

endmodule

