description:
Design a positive edge-triggered D flip-flop using NAND gates. The module takes a clock signal (clk) and a data input (d), and outputs a stored value (q) that reflects the input data on the rising edge of the clock. The internal logic is implemented with a combination of NAND gates, enabling it to store a binary value until the next clock edge, effectively maintaining state in digital circuits.
module top_module(
    input clk,
    input d,
    output reg q
);

code:
module top_module(
    input clk,
    input d,
    output reg q
);wire n1, n2, n3, n4;

  // Positive edge-triggered D flip-flop using NAND gates
  // Q(t+1) = D & ~CLK & Q(t)
  // ~Q(t+1) = ~D & ~CLK & ~Q(t)
  // Q(t+1) = ~(~D & ~CLK & ~Q(t))
  // ~Q(t+1) = ~(D & ~CLK & Q(t))

  assign n1 = ~(d & ~clk & q);
  assign n2 = ~(~d & ~clk & ~q);
  assign n3 = ~(n1 & ~clk & n4);
  assign n4 = ~(n2 & ~clk & n3);

  always @(posedge clk) begin
    q <= n3;
  end

endmodule

