module top_module(clk, rst_b, enable, remove_flag, wtdg_rstrt, wtdg_rst_b, flag);input clk, rst_b, enable, remove_flag, wtdg_rstrt;
output wtdg_rst_b, flag;

wire clk, rst_b, enable, remove_flag, wtdg_rstrt, wtdg_rst_b;

parameter counter_width=2;
parameter count_limit=2'h3;

reg [(counter_width-1):0] counter;
reg flag;

assign wtdg_rst_b = (|counter) || ~enable;

always @(posedge clk) begin
   if (~rst_b) begin
      flag <= 1'b0;
      counter <= count_limit;
   end
   else begin
      if (enable) begin
         if (~wtdg_rst_b) begin
            flag <= 1'b1;
         end
         else begin
            if (remove_flag) begin
               flag <= 1'b0;
            end
         end
         if (wtdg_rstrt) begin
            counter <= count_limit;
         end
         else begin
            counter <= counter - 1;
         end
      end
   end
end

endmodule

