code:
module top_module(dout,
    wr_clk,
    rd_clk,
    I1,
    tmp_ram_rd_en,
    Q,
    O2,
    O1,
    din);output reg [63:0] dout; // Change to reg, since dout is driven in an always block
  input wr_clk;
  input rd_clk;
  input I1;
  input tmp_ram_rd_en;
  output [0:0] Q; // Q should be output
  output reg [11:0] O2; // Change to reg, since O2 is driven in an always block
  output reg [11:0] O1; // Change to reg, since O1 is driven in an always block
  input [63:0] din;

  reg [63:0] fifo_mem [0:63]; // 64-bit FIFO memory
  reg [5:0] wr_ptr = 0; // write pointer
  reg [5:0] rd_ptr = 0; // read pointer
  reg full = 0; // flag to indicate FIFO full
  wire empty = (wr_ptr == rd_ptr) && !full; // flag to indicate FIFO empty

  // Write operation
  always @(posedge wr_clk) begin
    if (I1 && !full) begin
      fifo_mem[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      if (wr_ptr == rd_ptr) full <= 1;
    end
  end

  // Read operation
  always @(posedge rd_clk) begin
    if (tmp_ram_rd_en && !empty) begin
      dout <= fifo_mem[rd_ptr];
      rd_ptr <= rd_ptr + 1;
      if (full) full <= 0;
    end
  end

  assign Q = full;

  always @* begin // Combinational logic always block to drive O1 and O2
    O1 = empty ? 0 : rd_ptr[5:0];
    O2 = full ? 0 : wr_ptr[5:0];
  end

endmodule

