always @(posedge clk) begin
    Q_reg2 <= Q_reg1;
end

always @(posedge clk) begin
    Q_reg3 <= Q_reg2;
end

always @(posedge clk) begin
    Q_reg4 <= Q_reg3;
end

always @(posedge clk or posedge reset) begin
    if (reset) begin
        Q <= 4'b0000;
    end else begin
        Q <= Q_reg4 + 1;
    end
end

endmodule

