module up_down_counter (
	input clk,
	input reset_n,
	input up,
	output [3:0] count);reg [3:0] count_reg = 4'b0000;

	always @(posedge clk or negedge reset_n) begin
		if (!reset_n)
			count_reg <= 4'b0000;
		else if (up)
			count_reg <= count_reg + 1;
		else
			count_reg <= count_reg - 1;
	end

	assign count = count_reg;

endmodule

