module counter3bit_tc (
	input clk,
	input rst,
	output reg [2:0] q,
	output tc);

	always @(posedge clk or posedge rst) begin
		if (rst)
			q <= 3'b000;
		else
			q <= q + 1;
	end

	assign tc = (q == 3'b111) ? 1 : 0;

endmodule

