description:
Design a 3-bit binary counter that increments on every positive edge of the clock signal, clk_i. The counter resets to zero when the reset signal, rst_i, is asserted. Initially, it waits in the IDLE state and transitions to the COUNT state to begin counting. If the counter reaches its maximum value (111 in binary), it resets to zero and returns to the IDLE state, maintaining its functionality in a continuous counting loop as long as the reset is not activated.
module top_module(
        input clk_i,
        input rst_i,
        output reg [2:0] count_o
    );

code:
module top_module(
        input clk_i,
        input rst_i,
        output reg [2:0] count_o
    );// Define the states of the finite state machine
    parameter [1:0] IDLE = 2'b00;
    parameter [1:0] COUNT = 2'b01;

    // Define the current state of the finite state machine
    reg [1:0] state;

    always @(posedge clk_i, posedge rst_i) begin
        if (rst_i) begin
            // Reset the counter to zero
            state <= IDLE;
            count_o <= 3'b0;
        end
        else begin
            case (state)
                IDLE: begin
                    // Wait for the next clock cycle to start counting
                    state <= COUNT;
                end
                COUNT: begin
                    // Increment the counter and reset it to zero if it reaches its maximum value
                    if (count_o == 3'b111) begin
                        count_o <= 3'b0;
                        state <= IDLE;
                    end
                    else begin
                        count_o <= count_o + 3'b1;
                        state <= COUNT;
                    end
                end
                default: begin
                    // Should never happen
                    state <= IDLE;
                    count_o <= 3'b0;
                end
            endcase
        end
    end
endmodule

