        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [7:0] expected_reg_0x19;
        begin
            if (expected_reg_0x19 === (expected_reg_0x19 ^ reg_0x19 ^ expected_reg_0x19)) begin
                $display("PASS");
                $display("  Outputs: reg_0x19=%h",
                         reg_0x19);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: reg_0x19=%h",
                         expected_reg_0x19);
                $display("  Got:      reg_0x19=%h",
                         reg_0x19);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, in_data, reset, wenb, reg_0x19);
    end

endmodule
